const c = new pg.Client({ connectionString: process.env.DATABASE_URL, ssl: { rejectUnauthorized: false }, connectionTimeoutMillis: 10000 });
(async () => {
  await c.connect();
  console.log("Connected as", (await c.query("select current_user, current_database()")).rows[0]);
  const t = await c.query(`select table_schema, table_name from information_schema.tables where table_schema not in (\x27pg_catalog\x27,\x27information_schema\x27) order by 1,2`);
  console.log("Tables:", t.rows);
  const cols = await c.query(`select table_name, column_name, data_type, udt_name, is_nullable, column_default from information_schema.columns where table_name in (\x27scores\x27,\x27scenarios\x27) order by table_name, ordinal_position`);
  console.table(cols.rows);
  const k = await c.query(`select conname, contype, pg_get_constraintdef(oid) def from pg_constraint where conrelid = to_regclass(\x27scores\x27)`);
